package beer

import (
	"errors"
	"fmt"
	"strings"
)

const maxVerse = 99

// verseOutOfRange reports whether n is not a valid verse number.
func verseOutOfRange(n int) bool {
	return n < 0 || n > maxVerse
}

// bottles renders the count of bottles, e.g. "no more bottles",
// "1 bottle", or "99 bottles".
func bottles(n int) string {
	switch {
	case n == 0:
		return "no more bottles"
	case n == 1:
		return "1 bottle"
	default:
		return fmt.Sprintf("%d bottles", n)
	}
}

// Verse returns the verse for the given number of bottles,
// or an error if n is out of range.
func Verse(n int) (string, error) {
	if verseOutOfRange(n) {
		return "", errors.New("verse number out of range")
	}

	if n == 0 {
		return "No more bottles of beer on the wall, no more bottles of beer.\n" +
			"Go to the store and buy some more, 99 bottles of beer on the wall.\n", nil
	}

	action := "Take one down"
	if n == 1 {
		action = "Take it down"
	}

	return fmt.Sprintf("%s of beer on the wall, %s of beer.\n",
		strings.Title(bottles(n)), strings.Title(bottles(n))) +
		fmt.Sprintf("%s and pass it around, %s of beer on the wall.\n", action, bottles(n-1)), nil
}

// Verses returns the verses from start down to and including stop,
// or an error if the range is invalid.
func Verses(start, stop int) (string, error) {
	if start < stop || verseOutOfRange(start) || verseOutOfRange(stop) {
		return "", errors.New("invalid verse range")
	}

	var sb strings.Builder
	for n := start; n >= stop; n-- {
		v, err := Verse(n)
		if err != nil {
			return "", err
		}
		sb.WriteString(v)
	}
	return sb.String(), nil
}

// Song returns the entire song, from 99 bottles down to none.
func Song() string {
	song, err := Verses(maxVerse, 0)
	if err != nil {
		panic(err) // unreachable: the full range is always valid
	}
	return song
}

